window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9d4fa80575807d2f"]={"versions": [{"id": "FIG-9d4fa80575807d2f", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Teilschritts „Write CRC“ innerhalb des AUTOSAR E2E-Profils 4 (E2E Profile 4). Das Diagramm beschreibt die Serialisierung des Prüfsummenwerts in den Nutzdatenpuffer im Rahmen der Schutzfunktion <code>E2E_P04Protect()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P04Protect()</code> (als UML-Aktions-/Kollaborationssymbol dargestellt).\n</li><li><strong>Variablen &amp; Puffer</strong>:\n<ul class=\"fig-list\"><li><code>CRC</code>: Lokale Variable (4 Byte).\n</li><li><code>Data[]</code>: Byte-Array / Übertragungspuffer.\n</li><li><code>Offset</code>: Konfigurationsparameter / Offset-Index im Datenpuffer.\n</li></ul>\n</li><li><strong>Knotenelemente</strong>: Initialknoten (Start), Aktionszustand <code>Copy 4-byte local variable CRC on bytes Data[Offset+8...Offset+11] using big Endian order</code>, Aktivitätsendknoten (Stop).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten.\n</li><li>Ausführung der Aktion: Der 4-Byte-Wert der lokalen Variable <code>CRC</code> wird in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in das Byte-Array auf die Indizes <code>Data[Offset+8]</code> bis <code>Data[Offset+11]</code> kopiert.\n</li><li>Kontrollflussübergang zum Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Vorgabe für die Implementierung von <code>E2E_P04Protect()</code> gemäß Anforderung <code>[PRS_E2E_00368]</code>.\n</li><li>Die 32-Bit-Prüfsumme belegt exakt vier aufeinanderfolgende Bytes ab <code>Offset + 8</code>.\n</li><li>Die Bytereihenfolge muss zwingend Big-Endian sein, unabhängig von der zugrunde liegenden Endianness der Host-CPU/Mikrocontroller-Architektur.\n</li></ul>"}, {"id": "FIG-6103caa9e160a409", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Teilschritts „Write CRC“ innerhalb des AUTOSAR E2E-Profils 4 (E2E Profile 4). Das Diagramm beschreibt die Serialisierung des Prüfsummenwerts in den Nutzdatenpuffer im Rahmen der Funktionen <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code> (jeweils als UML-Aktions-/Kollaborationssymbol annotiert).\n</li><li><strong>Variablen &amp; Puffer</strong>:\n<ul class=\"fig-list\"><li><code>CRC</code>: Lokale Variable (4 Byte).\n</li><li><code>Data[]</code>: Byte-Array / Übertragungspuffer.\n</li><li><code>Offset</code>: Konfigurationsparameter / Offset-Index im Datenpuffer.\n</li></ul>\n</li><li><strong>Knotenelemente</strong>: Initialknoten (Start), Aktionszustand <code>Copy 4-byte local variable CRC on bytes Data[Offset+8...Offset+11] using big Endian order</code>, Aktivitätsendknoten (Stop).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten.\n</li><li>Ausführung der Aktion: Der 4-Byte-Wert der lokalen Variable <code>CRC</code> wird in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in das Byte-Array auf die Indizes <code>Data[Offset+8]</code> bis <code>Data[Offset+11]</code> kopiert.\n</li><li>Kontrollflussübergang zum Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Vorgabe für die Implementierung der Schutz- und Weiterleitungsfunktionen <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code>.\n</li><li>Die 32-Bit-Prüfsumme belegt exakt vier aufeinanderfolgende Bytes ab <code>Offset + 8</code>.\n</li><li>Die Bytereihenfolge muss zwingend Big-Endian sein, unabhängig von der zugrunde liegenden Endianness der Host-CPU/Mikrocontroller-Architektur.\n</li></ul>"}, {"id": "FIG-9c08a0e73c27a275", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Teilschritts „Write CRC“ innerhalb des AUTOSAR E2E-Profils 4 (E2E Profile 4). Das Diagramm beschreibt die Serialisierung des Prüfsummenwerts in den Nutzdatenpuffer im Rahmen der Funktionen <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code> (jeweils als UML-Aktions-/Kollaborationssymbol annotiert).\n</li><li><strong>Variablen &amp; Puffer</strong>:\n<ul class=\"fig-list\"><li><code>CRC</code>: Lokale Variable (4 Byte).\n</li><li><code>Data[]</code>: Byte-Array / Übertragungspuffer.\n</li><li><code>Offset</code>: Konfigurationsparameter / Offset-Index im Datenpuffer.\n</li></ul>\n</li><li><strong>Knotenelemente</strong>: Initialknoten (Start), Aktionszustand <code>Copy 4-byte local variable CRC on bytes Data[Offset+8...Offset+11] using big Endian order</code>, Aktivitätsendknoten (Stop).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt über den Initialknoten.\n</li><li>Ausführung der Aktion: Der 4-Byte-Wert der lokalen Variable <code>CRC</code> wird in Big-Endian-Byte-Reihenfolge (Most Significant Byte zuerst) in das Byte-Array auf die Indizes <code>Data[Offset+8]</code> bis <code>Data[Offset+11]</code> kopiert.\n</li><li>Kontrollflussübergang zum Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verbindliche Vorgabe für die Implementierung der Schutz- und Weiterleitungsfunktionen <code>E2E_P04Protect()</code> und <code>E2E_P04Forward()</code>.\n</li><li>Die 32-Bit-Prüfsumme belegt exakt vier aufeinanderfolgende Bytes ab <code>Offset + 8</code>.\n</li><li>Die Bytereihenfolge muss zwingend Big-Endian sein, unabhängig von der zugrunde liegenden Endianness der Host-CPU/Mikrocontroller-Architektur.\n</li></ul>"}], "trans": [{"from": "FIG-9d4fa80575807d2f", "to": "FIG-6103caa9e160a409", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung der Aufruf-Annotation <code>E2E_P04Forward()</code> unterhalb von <code>E2E_P04Protect()</code>, wodurch der Teilschritt „Write CRC“ normativ auch für die Weiterleitungsfunktion spezifiziert wird.\n</li></ul>"}, {"from": "FIG-6103caa9e160a409", "to": "FIG-9c08a0e73c27a275", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
